import React, { useState, useEffect, useRef } from 'react';
import { LiveKitRoom, useRemoteParticipants, useConnectionState } from '@livekit/components-react';
import { ConnectionState } from 'livekit-client';
import '@livekit/components-styles';
import { supabase } from '../../utils/supabaseClient';
import Icon from '../AppIcon';
import Button from '../ui/Button';
import { useToast } from '../../contexts/ToastContext';
import { peerSyncService } from '../../services/peerSyncService';
import { supabaseService } from '../../services/supabaseService';
import SharedScratchpad from './SharedScratchpad';
import SecureVideoConference from './SecureVideoConference';

const ReconnectionOverlay = ({ graceTimeLeft }) => (
    <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-md flex flex-col items-center justify-center z-50 p-6 text-center animate-in fade-in duration-300">
        <div className="w-16 h-16 border-4 border-amber-500 border-t-transparent rounded-full animate-spin mb-6 shadow-[0_0_30px_rgba(245,158,11,0.2)]" />
        <h3 className="text-xl font-black text-white italic mb-2 uppercase tracking-tighter">Partner Disconnected</h3>
        <p className="text-slate-400 text-sm max-w-xs mb-8">
            Holding the room for <span className="text-amber-500 font-bold">{graceTimeLeft}s</span>. If they don't reconnect, we'll return to the video.
        </p>
        <div className="flex items-center gap-2 px-4 py-2 bg-amber-500/10 border border-amber-500/20 rounded-full">
            <div className="w-2 h-2 bg-amber-500 rounded-full animate-ping" />
            <span className="text-[10px] font-bold text-amber-500 uppercase tracking-widest">Awaiting Reconnection...</span>
        </div>
    </div>
);

const ConnectionStatusManager = ({ isSolo, isComplete, onAbandoned }) => {
    const remoteParticipants = useRemoteParticipants();
    const connectionState = useConnectionState();
    const [graceTimeLeft, setGraceTimeLeft] = useState(30);
    const [isReconnecting, setIsReconnecting] = useState(false);
    const hasSeenPartner = useRef(false);

    useEffect(() => {
        if (!isSolo && remoteParticipants.length > 0) {
            hasSeenPartner.current = true;
            setIsReconnecting(false);
            setGraceTimeLeft(30);
        }
    }, [remoteParticipants.length, isSolo]);

    useEffect(() => {
        // If partner drops after session started
        if (!isSolo && hasSeenPartner.current && remoteParticipants.length === 0 && !isComplete) {
            setIsReconnecting(true);
        }
    }, [remoteParticipants.length, isSolo, isComplete]);

    useEffect(() => {
        let timer;
        if (isReconnecting && graceTimeLeft > 0) {
            timer = setInterval(() => {
                setGraceTimeLeft(prev => {
                    if (prev <= 1) {
                        clearInterval(timer);
                        onAbandoned();
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
        }
        return () => clearInterval(timer);
    }, [isReconnecting, graceTimeLeft, onAbandoned]);

    if (isReconnecting) return <ReconnectionOverlay graceTimeLeft={graceTimeLeft} />;
    
    // Also show standard LiveKit reconnection if LOCAL user drops
    if (connectionState === ConnectionState.Reconnecting) {
        return (
            <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md flex flex-col items-center justify-center z-50 p-6 text-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4" />
                <p className="text-white font-bold tracking-widest text-xs uppercase animate-pulse">Your connection is unstable...</p>
                <p className="text-slate-400 text-[10px] mt-2">Attempting to reconnect you to the room.</p>
            </div>
        );
    }

    return null;
};

const WaitingOverlay = ({ isSolo }) => {
    const remoteParticipants = useRemoteParticipants();
    
    // If it's a solo session, or if there's at least one remote partner, don't show the overlay
    if (isSolo || remoteParticipants.length > 0) return null;

    return (
        <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm flex flex-col items-center justify-center z-[5] pointer-events-none">
            <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4" />
            <p className="text-white font-bold tracking-widest text-sm uppercase animate-pulse">
                Waiting for partner to join...
            </p>
            <p className="text-muted-foreground text-xs mt-2 text-center max-w-xs">
                Your partner has been matched. They are reading the prompt and will be here momentarily.
            </p>
        </div>
    );
};

const PeerSyncLiveRoom = ({ courseId, moduleId, roomId, isSolo, onCheckpointCleared }) => {
    const { addToast } = useToast();
    const [token, setToken] = useState(null);
    const [timeLeft, setTimeLeft] = useState(isSolo ? 180 : 300); // 3 mins solo, 5 mins peer
    const [isComplete, setIsComplete] = useState(false);
    const [isConnecting, setIsConnecting] = useState(true);
    const [showRatingPrompt, setShowRatingPrompt] = useState(false);
    const [isSubmittingRating, setIsSubmittingRating] = useState(false);

    // 1. Fetch the LiveKit Token
    useEffect(() => {
        const fetchToken = async () => {
            try {
                const { data: { user } } = await supabase.auth.getUser();
                if (!user) throw new Error("Authentication required");

                const participantName = user.user_metadata?.full_name || user.email?.split('@')[0] || "Student";
                
                const { data, error } = await supabase.functions.invoke('get-livekit-token', {
                    body: { 
                        roomName: `peer_sync_${roomId}`, 
                        identity: user.id, // LiveKit requires a unique identity
                        name: participantName // Optional display name
                    }
                });

                if (error) throw error;
                if (data?.token) {
                    setToken(data.token);
                } else {
                    throw new Error("Invalid token format received");
                }
            } catch (error) {
                console.error("Failed to fetch LiveKit token:", error);
                addToast("Failed to connect to the secure video room.", "error");
            }
        };

        fetchToken();
    }, [roomId, addToast]);

    // 2. The 5-Minute Active Learning Timer
    useEffect(() => {
        if (!token || isComplete) return;

        const timer = setInterval(() => {
            setTimeLeft((prev) => {
                if (prev <= 1) {
                    clearInterval(timer);
                    handleSessionComplete();
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(timer);
    }, [token, isComplete]);

    const handleSessionComplete = async () => {
        setIsComplete(true);
        
        try {
            const { data: { user } } = await supabase.auth.getUser();
            
            // Record the completion in the database to unlock the module
            await supabase.from('peer_sync_checkpoints').upsert([{
                user_id: user.id,
                course_id: courseId,
                module_id: moduleId,
                is_completed: true,
                is_bypassed: isSolo || false,
                session_id: roomId // Using roomId as the session reference
            }], {
                onConflict: 'user_id,course_id,module_id',
                ignoreDuplicates: true
            });

            if (isSolo) {
                addToast("Feynman Bypass Complete! Knowledge locked in.", "success");
                onCheckpointCleared();
            } else {
                // Award the Sync Bounty!
                await peerSyncService.awardSyncBounty(roomId);

                // Expire any chat shoutouts for this checkpoint
                await supabaseService.expireSyncShoutouts(courseId, moduleId);

                addToast("Peer Sync Complete! Bounty Awarded 💎", "success");
                setShowRatingPrompt(true);
            }
        } catch (error) {
            console.error("Failed to save checkpoint:", error);
            // If it fails to save due to unique constraint (already saved), just proceed
            if (isSolo) {
                onCheckpointCleared();
            } else {
                setShowRatingPrompt(true);
            }
        }
    };

    const handleRatingSubmit = async (rating) => {
        setIsSubmittingRating(true);
        try {
            if (rating !== 'skipped') {
                await peerSyncService.submitPeerRating(roomId, rating);
            }
            
            if (rating === 'good') {
                addToast("Glad you had a great session!", "success");
            } else if (rating === 'bad') {
                addToast("Thanks for the feedback. We'll adjust matchmaking.", "info");
            }
        } catch (e) {
            console.error(e);
        } finally {
            onCheckpointCleared();
        }
    };

    const formatTime = (seconds) => {
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}:${s < 10 ? '0' : ''}${s}`;
    };

    if (!token) {
        return (
            <div className="w-full h-full bg-slate-950 rounded-3xl flex flex-col items-center justify-center border border-border overflow-hidden relative shadow-2xl">
                <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="text-white font-bold tracking-widest text-sm uppercase">Securing Connection...</p>
            </div>
        );
    }

    if (showRatingPrompt) {
        return (
            <div className="w-full h-full bg-slate-950 rounded-3xl border border-border/50 overflow-hidden shadow-2xl flex flex-col relative animate-in fade-in zoom-in-95 duration-500 items-center justify-center p-6 text-center">
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-5"></div>
                
                <div className="relative z-10 flex flex-col items-center space-y-6 max-w-sm">
                    <div className="w-20 h-20 bg-emerald-500/10 rounded-full flex items-center justify-center mb-2 shadow-[0_0_30px_rgba(16,185,129,0.2)]">
                        <Icon name="Star" size={40} className="text-emerald-400" />
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-white italic mb-2">Session Complete!</h2>
                        <p className="text-slate-400 text-sm">How would you rate your peer learning session? Your feedback ensures high-quality matches.</p>
                    </div>
                    
                    <div className="flex items-center justify-center gap-6 mt-6 w-full">
                        <button 
                            disabled={isSubmittingRating}
                            onClick={() => handleRatingSubmit('bad')}
                            className="flex flex-col items-center justify-center gap-3 h-28 w-28 rounded-2xl border-2 border-red-500/30 bg-slate-900/50 hover:bg-red-500/10 hover:border-red-500 transition-all group"
                        >
                            <div className="p-3 bg-red-500/10 rounded-full group-hover:scale-110 transition-transform">
                                <Icon name="ThumbsDown" size={28} className="text-red-400" />
                            </div>
                            <span className="text-xs font-bold text-red-400 uppercase tracking-widest">Poor</span>
                        </button>
                        
                        <button 
                            disabled={isSubmittingRating}
                            onClick={() => handleRatingSubmit('good')}
                            className="flex flex-col items-center justify-center gap-3 h-28 w-28 rounded-2xl border-2 border-emerald-500/30 bg-slate-900/50 hover:bg-emerald-500/10 hover:border-emerald-500 transition-all group"
                        >
                            <div className="p-3 bg-emerald-500/10 rounded-full group-hover:scale-110 transition-transform">
                                <Icon name="ThumbsUp" size={28} className="text-emerald-400" />
                            </div>
                            <span className="text-xs font-bold text-emerald-400 uppercase tracking-widest">Great!</span>
                        </button>
                    </div>
                    
                    <button 
                        disabled={isSubmittingRating}
                        className="text-slate-500 text-xs font-bold hover:text-white uppercase tracking-wider mt-4 transition-colors" 
                        onClick={() => handleRatingSubmit('skipped')}
                    >
                        Skip for now
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="w-full h-full bg-slate-950 rounded-3xl border border-border/50 overflow-hidden shadow-2xl flex flex-col relative animate-in fade-in zoom-in-95 duration-500">
            
            {/* Control Header */}
            <div className="h-10 sm:h-16 bg-slate-900 border-b border-white/10 px-3 sm:px-6 flex items-center justify-between z-10 shrink-0">
                <div className="flex items-center gap-2 sm:gap-3">
                    <div className="w-2 h-2 sm:w-3 sm:h-3 rounded-full bg-emerald-500 animate-pulse" />
                    <h3 className="text-white font-bold text-xs sm:text-sm hidden sm:block">
                        {isSolo ? 'Feynman Explanation' : 'Active Peer Sync'}
                    </h3>
                </div>

                <div className="flex items-center gap-2 sm:gap-4">
                    <div className="px-2 py-1 sm:px-4 sm:py-1.5 bg-primary/20 border border-primary/30 rounded-full flex items-center gap-1 sm:gap-2">
                        <Icon name="Timer" size={14} className="text-primary" />
                        <span className="text-primary font-mono font-bold tracking-wider text-[10px] sm:text-base">{formatTime(timeLeft)}</span>
                    </div>
                </div>
            </div>

            {/* LiveKit Video Room & Scratchpad */}
            <div className="flex-1 flex flex-col md:flex-row overflow-hidden relative">
                {/* Left Side: Video */}
                <div className="flex-1 h-full relative bg-black/50">
                    <LiveKitRoom
                        video={true}
                        audio={true}
                        token={token}
                        serverUrl={import.meta.env.VITE_LIVEKIT_URL}
                        data-lk-theme="default"
                        style={{ height: '100%', width: '100%' }}
                        onConnected={() => setIsConnecting(false)}
                        onDisconnected={() => {
                            if (!isComplete) {
                                addToast("Partner disconnected. You can try again.", "warning");
                            }
                        }}
                    >
                        <SecureVideoConference />
                        <WaitingOverlay isSolo={isSolo} />
                        <ConnectionStatusManager 
                            isSolo={isSolo} 
                            isComplete={isComplete} 
                            onAbandoned={() => {
                                addToast("Partner failed to reconnect. Please try again.", "warning");
                                onCheckpointCleared(false);
                            }} 
                        />
                    </LiveKitRoom>

                    {/* Loading Overlay until connection to server is established */}
                    {isConnecting && (
                        <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-md flex flex-col items-center justify-center z-10">
                            <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4" />
                            <p className="text-white font-bold animate-pulse tracking-widest text-sm uppercase">
                                {isSolo ? 'Initializing Camera...' : 'Connecting to Server...'}
                            </p>
                        </div>
                    )}
                </div>

                {/* Right Side: Shared Scratchpad */}
                <div className="w-full md:w-80 lg:w-96 h-64 md:h-full border-t md:border-t-0 md:border-l border-white/10 shrink-0">
                    <SharedScratchpad roomId={roomId} isSolo={isSolo} />
                </div>
            </div>

            {/* Emergency Bypass Button */}
            <div className="absolute top-1 sm:top-4 right-1 sm:right-4 z-20">
                 <Button 
                    variant="ghost" 
                    size="sm" 
                    className="text-[10px] sm:text-sm text-white/50 hover:bg-white/10 hover:text-white px-2 py-1 h-auto sm:h-9"
                    onClick={() => {
                        if (window.confirm("Are you sure you want to exit? The module will not be unlocked until you complete a sync.")) {
                            onCheckpointCleared(false); // Pass false or handle exit without unlocking
                        }
                    }}
                >
                    Exit
                </Button>
            </div>
        </div>
    );
};

export default PeerSyncLiveRoom;
