import { supabase } from '../utils/supabaseClient';
import { supabaseService } from './supabaseService';

export const peerSyncService = {
    // 1. Enter the waiting room & perform matchmaking
    async joinQueue(courseId, moduleId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) throw new Error('User not authenticated');

            // Step 1: Clean up any old dangling queue entries for this user to ensure a fresh search
            await supabase
                .from('peer_sync_queue')
                .delete()
                .eq('user_id', user.id)
                .eq('status', 'waiting');

            // Step 2: Search for another user waiting for the exact same module
            const { data: potentialMatches } = await supabase
                .from('peer_sync_queue')
                .select('*')
                .eq('course_id', courseId)
                .eq('module_id', moduleId)
                .eq('status', 'waiting')
                .neq('user_id', user.id)
                .order('created_at', { ascending: true })
                .limit(1);

            const partner = potentialMatches && potentialMatches.length > 0 ? potentialMatches[0] : null;

            if (partner) {
                // MATCH FOUND! 
                // A. Update the partner's status to matched
                await supabase
                    .from('peer_sync_queue')
                    .update({ status: 'matched', matched_with: user.id })
                    .eq('id', partner.id);

                // B. Insert ourself as matched instantly
                const { data: matchedData, error: matchError } = await supabase
                    .from('peer_sync_queue')
                    .insert([{
                        user_id: user.id,
                        course_id: courseId,
                        module_id: moduleId,
                        status: 'matched',
                        matched_with: partner.user_id
                    }])
                    .select()
                    .single();

                if (matchError) throw matchError;

                // Create a secure peer session room
                await supabase
                    .from('peer_sessions')
                    .insert([{
                        course_id: courseId,
                        module_id: moduleId,
                        user1_id: partner.user_id,
                        user2_id: user.id,
                        is_solo_bypass: false,
                        is_async_match: true, // They were waiting, we joined them!
                        status: 'active'
                    }]);

                return matchedData;
            } else {
                // NO MATCH FOUND. Insert ourself into the waiting queue.
                const { data: waitingData, error: waitError } = await supabase
                    .from('peer_sync_queue')
                    .insert([{
                        user_id: user.id,
                        course_id: courseId,
                        module_id: moduleId,
                        status: 'waiting'
                    }])
                    .select()
                    .single();

                if (waitError) throw waitError;
                return waitingData;
            }
        } catch (error) {
            console.error('Error joining queue/matchmaking:', error);
            throw error;
        }
    },

    // Award Bounty (RPC call to database function)
    async awardSyncBounty(sessionId) {
        try {
            // 1. Get session details and check if already awarded
            const { data: session } = await supabase
                .from('peer_sessions')
                .select('user1_id, user2_id, is_async_match, bounty_awarded')
                .eq('id', sessionId)
                .single();

            if (session && !session.bounty_awarded && session.user1_id && session.user2_id) {
                // 2. Mark as awarded instantly to prevent double-award from partner's client
                await supabase
                    .from('peer_sessions')
                    .update({ bounty_awarded: true })
                    .eq('id', sessionId);

                // 3. Call the RPC function to update profiles and award badges
                await supabase.rpc('award_sync_bounty', {
                    p_user1_id: session.user1_id,
                    p_user2_id: session.user2_id,
                    p_is_async: session.is_async_match || false
                });

                // Award LUC Credits for successful Peer Sync (Incentive)
                await Promise.all([
                    supabaseService.processWalletTransaction(session.user1_id, 20, 'peer_sync', 'Completed Peer Sync session', `sync_${sessionId}`),
                    supabaseService.processWalletTransaction(session.user2_id, 20, 'peer_sync', 'Completed Peer Sync session', `sync_${sessionId}`)
                ]).catch(err => console.error("Peer sync credit reward failed:", err));

                return true;
            }
        } catch (error) {
            console.error('Error awarding bounty:', error);
        }
        return false;
    },

    // 2. Leave the waiting room
    async leaveQueue(queueId) {
        try {
            const { error } = await supabase
                .from('peer_sync_queue')
                .update({ status: 'cancelled' })
                .eq('id', queueId);
            
            if (error) throw error;
            return true;
        } catch (error) {
            console.error('Error leaving queue:', error);
            throw error;
        }
    },

    // 3. Listen for a match via Supabase Realtime
    subscribeToQueue(queueId, onMatchFound) {
        const subscription = supabase
            .channel(`queue:${queueId}`)
            .on(
                'postgres_changes',
                {
                    event: 'UPDATE',
                    schema: 'public',
                    table: 'peer_sync_queue',
                    filter: `id=eq.${queueId}`
                },
                (payload) => {
                    if (payload.new.status === 'matched') {
                        onMatchFound(payload.new);
                    }
                }
            )
            .subscribe();

        return () => {
            supabase.removeChannel(subscription);
        };
    },

    // 4. The Feynman Bypass (Solo Mode)
    async activateSoloBypass(courseId, moduleId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            
            // Create a solo session
            const { data: session, error: sessionError } = await supabase
                .from('peer_sessions')
                .insert([{
                    course_id: courseId,
                    module_id: moduleId,
                    user1_id: user.id,
                    is_solo_bypass: true,
                    status: 'active'
                }])
                .select()
                .single();

            if (sessionError) throw sessionError;
            
            // We return the session so the LiveRoom can be launched
            // The checkpoint will only unlock AFTER the solo video is done!
            return session;
        } catch (error) {
            console.error('Error activating bypass:', error);
            throw error;
        }
    },

    // 5. Check if a module is unlocked
    async isCheckpointCleared(courseId, moduleId) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) return false;

            const { data, error } = await supabase
                .from('peer_sync_checkpoints')
                .select('*')
                .eq('user_id', user.id)
                .eq('course_id', courseId)
                .eq('module_id', moduleId)
                .maybeSingle();

            if (error && error.code !== 'PGRST116') {
                console.error('Error checking checkpoint:', error);
                return false;
            }

            return !!data; // True if record exists
        } catch (error) {
            console.error('Error:', error);
            return false;
        }
    },

    // 6. Submit Peer Rating
    async submitPeerRating(roomId, ratingScore) {
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) return;

            // ratingScore: 'good' or 'bad'
            // Assumes a peer_sync_ratings table exists in Supabase
            await supabase.from('peer_sync_ratings').insert([{
                rater_id: user.id,
                room_id: roomId,
                rating: ratingScore,
                created_at: new Date()
            }]);

            // Award micro-reward for providing peer feedback
            await supabaseService.processWalletTransaction(user.id, 5, 'peer_review', 'Provided peer feedback', `rating_${roomId}`).catch(e => {});
        } catch (error) {
            console.error('Error submitting peer rating:', error);
        }
    },

    // 7. Ping Async Waiters
    pingAsyncWaiters(courseId, moduleId, channelId = null) {
        // Send a broadcast to anyone listening on the course channel
        supabase.channel(`async_match_${courseId}`).send({
            type: 'broadcast',
            event: 'partner_arrived',
            payload: { moduleId, channelId }
        });
    }
};
