import React, { useEffect, useMemo, useRef, useCallback } from 'react';
import { Plyr } from 'plyr-react';
import "plyr-react/plyr.css";
import { cn } from '../../utils/cn';
import Icon from '../AppIcon';

/**
 * LUC Video Player
 * A custom player wrapper that uses Plyr.js to provide a premium, 
 * branded feel for YouTube videos while keeping users on-site.
 */
const VideoPlayer = ({
    videoId,
    title,
    className,
    poster = "",
    autoplay = false,
    allowSeek = true, // explicit prop to control seeking behavior
    forceWatch = true, // If true, prevents seeking past the furthest watched point
    initialTime = 0,   // Starting point
    onProgress, // Callback for progress updates (currentTime, duration, percentage)
    onReady    // Callback when player is ready
}) => {
    // We use a ref to access the Plyr instance via plyr-react's ForwardRef
    const apiRef = useRef(null);
    const maxWatchedRef = useRef(initialTime); // Track max watched time

    // Memoize the source and options to prevent unneeded re-renders
    const plyrSource = useMemo(() => ({
        type: 'video',
        sources: [
            {
                src: videoId,
                provider: 'youtube',
            },
        ],
    }), [videoId]);

    // We reset state in the main effect below to ensure proper ordering with initialTime
    // useEffect(() => {
    //     maxWatchedRef.current = initialTime;
    // }, [videoId, initialTime]);

    const plyrOptions = useMemo(() => ({
        autoplay: autoplay,
        hideControls: false,
        modestbranding: true,
        resetOnEnd: true,
        clickToPlay: true,
        seekTime: 10,
        title: title,
        youtube: {
            noCookie: true,
            rel: 0,
            showinfo: 0,
            iv_load_policy: 3,
            modestbranding: 1,
            controls: 1, // Ensure native controls are available if plyr fails
            origin: window.location.origin,
            enablejsapi: 1
        }
    }), [autoplay, title, allowSeek]);

    // Use refs to keep track of props without triggering re-runs of the setup effect
    const onProgressRef = useRef(onProgress);
    const initialSeekDoneRef = useRef(false);

    useEffect(() => {
        onProgressRef.current = onProgress;
    }, [onProgress]);

    // Track if we need to perform an initial seek
    const pendingSeekRef = useRef(initialTime > 0);
    const isSeekingRef = useRef(false);

    // Update pending seek if initialTime arrives later
    useEffect(() => {
        if (initialTime > 0 && !initialSeekDoneRef.current) {
            pendingSeekRef.current = true;
        }
    }, [initialTime]);

    // Reset for new video
    useEffect(() => {
        initialSeekDoneRef.current = false;
        isSeekingRef.current = false;
        pendingSeekRef.current = (initialTime > 0);
    }, [videoId]);

    // Function to perform the actual seek
    const performInitialSeek = useCallback((player, time) => {
        if (!player || !player.ready || initialSeekDoneRef.current || isSeekingRef.current || time <= 0) return;

        try {
            isSeekingRef.current = true;
            console.log(`[VideoPlayer] Attempting seek to ${time}...`);
            player.currentTime = time;
            maxWatchedRef.current = time;

            // For YouTube, verify it actually stuck
            setTimeout(() => {
                isSeekingRef.current = false;
                const diff = Math.abs(player.currentTime - time);
                if (diff < 3) { // Slightly wider margin for slow loading
                    console.log(`[VideoPlayer] Seek confirmed at ${player.currentTime}`);
                    initialSeekDoneRef.current = true;
                    pendingSeekRef.current = false;
                } else {
                    console.log(`[VideoPlayer] Seek verification failed (current: ${player.currentTime}, target: ${time}). Will retry...`);
                }
            }, 1000);
        } catch (e) {
            isSeekingRef.current = false;
            console.warn("[VideoPlayer] Seek error", e);
        }
    }, []);

    useEffect(() => {
        let playerInstance = null;
        let checkCount = 0;

        // Reset tracking on video change - strictly use initialTime
        maxWatchedRef.current = initialTime;

        const handleTimeUpdate = () => {
            const player = apiRef.current?.plyr;
            if (!player) return;

            // Safety catch: if we have a pending seek but we're playing at the start, force it
            if (pendingSeekRef.current && !isSeekingRef.current && player.currentTime < 1 && initialTime > 0) {
                performInitialSeek(player, initialTime);
            }

            // 2. Track furthest point - only increase maxWatched
            if (player.currentTime > maxWatchedRef.current && player.currentTime <= maxWatchedRef.current + 3) {
                maxWatchedRef.current = player.currentTime;
            }

            // 3. Force Watch logic - only trigger if we are significantly past the boundary
            if (forceWatch && player.currentTime > maxWatchedRef.current + 2) {
                player.currentTime = maxWatchedRef.current;
            }

            if (onProgressRef.current) {
                onProgressRef.current({
                    currentTime: player.currentTime,
                    duration: player.duration,
                    percentage: (player.currentTime / player.duration) * 100
                });
            }
        };

        const handleSeeking = () => {
            const player = apiRef.current?.plyr;
            if (!player) return;

            // 1. Cancel initial resume if user manually seeks somewhere else
            if (pendingSeekRef.current && !isSeekingRef.current) {
                const diffFromInitial = Math.abs(player.currentTime - initialTime);
                if (diffFromInitial > 5) { // User moved more than 5 seconds away
                    console.log("[VideoPlayer] User manual override detected, cancelling initial resume.");
                    pendingSeekRef.current = false;
                    initialSeekDoneRef.current = true;
                    // Also update maxWatched so they can play from this new spot
                    maxWatchedRef.current = player.currentTime;
                }
            }

            // 2. Force Watch logic: only block seeking FORWARD past maxWatched
            if (forceWatch && player.currentTime > maxWatchedRef.current + 1.5) { // Slightly more buffer
                console.log(`[VideoPlayer] Forward skip blocked. Max: ${maxWatchedRef.current}, Attempted: ${player.currentTime}`);
                player.currentTime = maxWatchedRef.current;
            }
        };

        const handleReady = () => {
            const player = apiRef.current?.plyr;
            if (player && onReady) onReady(player);
        };

        const checkInterval = setInterval(() => {
            const player = apiRef.current?.plyr;
            checkCount++;

            if (player && typeof player.on === 'function') {
                clearInterval(checkInterval);
                playerInstance = player;

                player.on('timeupdate', handleTimeUpdate);
                player.on('seeking', handleSeeking);
                player.on('ready', handleReady);

                if (player.ready && pendingSeekRef.current) {
                    performInitialSeek(player, initialTime);
                }

                if (player.ready) {
                    handleReady();
                }
            }

            // Fallback for cases where plyr.ready is true but seeking still fails initially
            if (playerInstance && pendingSeekRef.current && checkCount % 3 === 0) {
                performInitialSeek(playerInstance, initialTime);
            }

            if (checkCount > 150) {
                clearInterval(checkInterval);
            }
        }, 100);

        return () => {
            clearInterval(checkInterval);
            if (playerInstance && typeof playerInstance.off === 'function') {
                try {
                    // Plyr might have already destroyed its DOM elements (container is null)
                    playerInstance.off('timeupdate', handleTimeUpdate);
                    playerInstance.off('seeking', handleSeeking);
                    playerInstance.off('ready', handleReady);
                } catch (e) {
                    console.log("[VideoPlayer] Plyr already destroyed, skipping off() cleanup.");
                }
            }
        };
    }, [videoId, onReady, forceWatch, initialTime, performInitialSeek]);

    // Late seek trigger when prop updates
    useEffect(() => {
        const player = apiRef.current?.plyr;
        if (player && player.ready && pendingSeekRef.current) {
            performInitialSeek(player, initialTime);
        }
    }, [initialTime, performInitialSeek]);

    if (!videoId) {
        return (
            <div className={cn(
                "w-full aspect-video rounded-3xl overflow-hidden shadow-2xl bg-slate-950 border border-white/10 flex flex-col items-center justify-center p-6 text-center space-y-4",
                className
            )}>
                <div className="w-12 h-12 bg-red-500/10 rounded-full flex items-center justify-center text-red-500">
                    <Icon name="AlertTriangle" size={24} />
                </div>
                <div>
                    <h3 className="text-white font-bold">Video Unavailable</h3>
                    <p className="text-xs text-slate-400 max-w-xs mt-1">This lesson does not have a valid video source configured.</p>
                </div>
            </div>
        );
    }

    return (
        <div
            key={videoId}
            className={cn(
                "luc-video-wrapper w-full aspect-video rounded-3xl overflow-hidden shadow-2xl bg-black border border-white/10 group relative",
                className
            )}
        >
            <Plyr
                ref={apiRef}
                source={plyrSource}
                options={plyrOptions}
            />

            {/* Ultimate Click Shield: Disables all clicks on the YouTube iframe itself */}
            <style dangerouslySetInnerHTML={{ __html: `
                /* Disable all mouse interactions with the YouTube iframe */
                .luc-video-wrapper iframe {
                    pointer-events: none !important;
                }
                
                /* Ensure Plyr's custom click-to-play overlay still catches clicks */
                .luc-video-wrapper .plyr__video-wrapper {
                    pointer-events: auto !important;
                }
            `}} />

            {/* Branded Overlay */}
            <div className="absolute top-4 left-4 z-10 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                <div className="flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/20">
                    <img src="/luc.ico" alt="LUC logo" className="w-4 h-4" />
                    <span className="text-[10px] font-bold text-white uppercase tracking-widest">LUC Academy</span>
                </div>
            </div>
        </div>
    );
};

export default VideoPlayer;
