import React, { useRef, useState, useEffect } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import AcademyShareModal from './AcademyShareModal';
import { getAchievementTier } from '../../../utils/courseUtils';
import { cn } from '../../../utils/cn';
import { supabaseService } from '../../../services/supabaseService';

const Certificate = ({ course, studentName = "Learner", completionDate = new Date().toLocaleDateString(), userId }) => {
    const certificateRef = useRef(null);
    const [showShareModal, setShowShareModal] = useState(false);
    const [assignment, setAssignment] = useState(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchProofOfWork = async () => {
            if (!userId || !course.id) return;
            try {
                // Fetch the student's submission for this course
                const assignments = await supabaseService.getInstructorAssignments(course.instructor_id || course.instructorId);
                const studentWork = assignments.find(a => 
                    String(a.student_id) === String(userId) && 
                    String(a.course_id) === String(course.id) &&
                    a.status === 'passed'
                );
                setAssignment(studentWork);
            } catch (error) {
                console.error("Failed to fetch proof of work:", error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchProofOfWork();
    }, [userId, course.id]);

    // Tier Logic from shared utility
    const tier = getAchievementTier(course);
    const verificationId = `LUC-${course.id.slice(0, 4)}-${userId?.slice(0, 4)}`.toUpperCase();

    const handlePrint = () => {
        const originalTitle = document.title;
        document.title = `LUC Certificate - ${course.title} - ${studentName}`;
        window.print();
        document.title = originalTitle;
    };

    const isBadge = tier.label === 'SKILL BADGE';

    if (isBadge) {
        return (
            <div className="flex flex-col items-center gap-10 py-10 w-full animate-in zoom-in-50 duration-500">
                {/* --- The Badge Display --- */}
                <div
                    ref={certificateRef}
                    className="relative group print:shadow-none"
                    style={{ filter: 'drop-shadow(0 20px 40px rgba(8,145,178,0.3))' }}
                >
                    {/* Ring Glow */}
                    <div className="absolute inset-0 bg-secondary/30 blur-[80px] rounded-full opacity-50 group-hover:opacity-100 transition-opacity" />

                    {/* Outer Ring */}
                    <div className="relative w-80 h-80 md:w-[450px] md:h-[450px] bg-gradient-to-br from-slate-200 via-white to-slate-300 rounded-full p-4 shadow-2xl flex items-center justify-center border-4 border-white/50">
                        {/* Metallic Inner Border */}
                        <div className="absolute inset-4 rounded-full border-[10px] border-double border-slate-300 shadow-inner" />

                        {/* Glass Center */}
                        <div className="relative w-full h-full rounded-full bg-gradient-to-br from-secondary/10 to-primary/5 backdrop-blur-md overflow-hidden flex flex-col items-center justify-center text-center p-12">
                            {/* Watermark Pattern */}
                            <div className="absolute inset-0 opacity-[0.03] pointer-events-none select-none">
                                <Icon name="Zap" className="w-full h-full scale-150 rotate-12" />
                            </div>

                            {/* Logo */}
                            <img src="/luc.png" alt="LUC" className="w-16 h-auto mb-6 opacity-30 grayscale" />

                            {/* Achievement Icon */}
                            <div className="relative mb-6">
                                <div className="absolute inset-0 bg-secondary blur-2xl opacity-20 animate-pulse" />
                                <Icon name={tier.icon} className="w-24 h-24 md:w-32 md:h-32 text-secondary relative z-10" />
                            </div>

                            {/* Text Content */}
                            <div className="space-y-2 relative z-10">
                                <h3 className="text-sm font-black tracking-[0.3em] text-secondary uppercase italic">
                                    {tier.label}
                                </h3>
                                <h2 className="text-2xl md:text-3xl font-black text-primary leading-tight px-4 line-clamp-2 uppercase italic">
                                    {course.title}
                                </h2>
                                <div className="pt-4 flex flex-col items-center">
                                    <div className="h-[1px] w-20 bg-secondary/30 mb-2" />
                                    <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                                        AWARDED TO
                                    </p>
                                    <p className="text-base font-black text-primary truncate max-w-[250px] italic">
                                        {studentName}
                                    </p>
                                </div>
                            </div>

                            {/* Seal */}
                            <div className="absolute bottom-10 flex flex-col items-center">
                                <p className="text-[8px] font-black text-muted-foreground/60 tracking-tighter">
                                    VERIFIED BY LUC ACADEMY © {new Date().getFullYear()}
                                </p>
                                <p className="text-[6px] font-bold text-secondary tracking-widest mt-1 uppercase">ID: {verificationId}</p>
                            </div>
                        </div>
                    </div>

                    {/* Badge Seal Ribbons (Classic look) */}
                    <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-48 h-32 -z-10 flex justify-center gap-1 opacity-80">
                        <div className="w-12 h-32 bg-[#7a0019] shadow-lg" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 50% 80%, 0 100%)' }} />
                        <div className="w-12 h-32 bg-[#7a0019] shadow-lg translate-y-4" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 50% 80%, 0 100%)' }} />
                        <div className="w-12 h-32 bg-[#7a0019] shadow-lg" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 50% 80%, 0 100%)' }} />
                    </div>
                </div>

                {/* --- Controls --- */}
                <div className="flex flex-col items-center gap-4 mt-20">
                    <p className="text-sm font-bold text-muted-foreground italic max-w-xs text-center">
                        You've unlocked the <span className="text-secondary font-black">{course.title}</span> Badge!
                    </p>
                    <div className="flex gap-4">
                        <Button variant="outline" iconName="Share2" onClick={() => setShowShareModal(true)}>
                            Share Achievement
                        </Button>
                        <Button variant="primary" iconName="Download" onClick={handlePrint}>
                            Save Badge Image
                        </Button>
                    </div>
                </div>

                <AcademyShareModal
                    isOpen={showShareModal}
                    onClose={() => setShowShareModal(false)}
                    type="badge"
                    data={course}
                />
            </div>
        );
    }

    return (
        <div className="flex flex-col items-center gap-8 animate-in slide-in-from-bottom-5 duration-700">
            <div
                ref={certificateRef}
                className="relative w-full aspect-[1.414/1] bg-white text-slate-900 overflow-hidden shadow-2xl flex select-none print:shadow-none print:w-full print:h-screen print:absolute print:inset-0"
            >
                {/* --- Background Watermark --- */}
                <div className="absolute inset-0 flex items-center justify-center opacity-[0.05] pointer-events-none z-0">
                    <img src="/luc.png" alt="" className="w-1/2 object-contain grayscale" />
                </div>

                {/* --- Top Right Corner Logo --- */}
                <div className="absolute top-8 right-8 z-30 opacity-80">
                    <img src="/luc.png" alt="LUC Logo" className="w-16 h-auto" />
                </div>
                {/* --- Left Geometric Red Panel --- */}
                <div
                    className="absolute top-0 bottom-0 left-0 w-[35%] bg-[#7a0019] z-10"
                    style={{ clipPath: 'polygon(0 0, 100% 0, 75% 100%, 0 100%)' }}
                >
                    {/* Gold Edge Accent */}
                    <div
                        className="absolute inset-y-0 right-0 w-2 bg-[#d4af37] origin-bottom -skew-x-[14deg] translate-x-1"
                    />
                    
                    {/* Proof of Work Vertical Badge */}
                    <div className="absolute bottom-20 left-8 -rotate-90 origin-left">
                        <p className="text-[10px] font-black tracking-[0.4em] text-white/40 uppercase">
                            VERIFIABLE PROOF OF WORK • {verificationId}
                        </p>
                    </div>
                </div>

                {/* --- Bottom Right Corner Accent --- */}
                <div
                    className="absolute bottom-0 right-0 w-[15%] h-[30%] bg-[#7a0019] z-10"
                    style={{ clipPath: 'polygon(100% 0, 0% 100%, 100% 100%)' }}
                />
                <div
                    className="absolute bottom-0 right-0 w-[16%] h-[31%] bg-[#d4af37] z-0"
                    style={{ clipPath: 'polygon(100% 0, 0% 100%, 100% 100%)' }}
                />


                {/* --- Official Stamp & Custom Ribbon --- */}
                <div className="absolute top-[8%] left-[30%] -translate-x-1/2 z-30 flex flex-col items-center drop-shadow-2xl">
                    <div className="relative flex items-center justify-center">
                        <img
                            src="/stamp.png"
                            alt="Official Stamp"
                            className="w-56 h-auto relative z-10"
                        />
                        <div className="absolute z-20 text-center transform -rotate-12 mt-2">
                            <span className="block text-[#daa520] font-bold text-xs uppercase tracking-widest shadow-sm">LUC Academy</span>
                            <span className="block text-white font-bold text-2xl shadow-sm">VERIFIED</span>
                        </div>
                    </div>

                    <div className="absolute top-[60%] -z-10 w-24 h-40 translate-x-2">
                        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-16 h-40 bg-[#7a0019] shadow-md border-x-2 border-[#5a0012]"
                            style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 50% 85%, 0 100%)' }} />
                    </div>
                </div>

                {/* --- Main Content Area --- */}
                <div className="relative z-20 w-full h-full flex flex-col pl-[30%] pr-[5%] py-12 items-center text-center justify-between">

                    {/* Header Section */}
                    <div className="space-y-2 mt-8 w-full">
                        <h1 className="text-6xl md:text-7xl font-bold text-[#7a0019] tracking-tight uppercase font-sans">
                            Certificate
                        </h1>
                        <h2 className="text-xl font-bold tracking-[0.4em] text-slate-700 uppercase">
                            of Achievement
                        </h2>
                    </div>

                    {/* Recipient Section */}
                    <div className="space-y-6 w-full flex-1 flex flex-col justify-center">
                        <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">This certificate is proudly presented to</p>

                        <div className="py-4 w-full">
                            <h2 className="text-6xl md:text-8xl text-[#7a0019] font-normal leading-tight mx-auto" style={{ fontFamily: '"Great Vibes", cursive' }}>
                                {studentName}
                            </h2>
                            <div className="w-2/3 mx-auto h-[2px] bg-[#d4af37]/30 mt-4" />
                        </div>

                        <div className="w-3/4 mx-auto space-y-4">
                            <div className="space-y-1">
                                <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">
                                    For successfully completing the course
                                </p>
                                <h3 className="text-xl md:text-2xl font-bold text-slate-800 uppercase leading-relaxed italic">
                                    {course.title}
                                </h3>
                            </div>
                            
                            {/* Mastery Defense Section */}
                            {assignment && (
                                <div className="mt-4 p-4 bg-slate-50 rounded-2xl border border-slate-200 text-left relative">
                                    <div className="absolute top-2 right-4 flex items-center gap-1">
                                        <Icon name="ShieldCheck" size={10} className="text-success" />
                                        <span className="text-[8px] font-black text-success uppercase italic">Vetted Mastery</span>
                                    </div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Mastery Defense Excerpt:</p>
                                    <p className="text-[10px] text-slate-600 leading-relaxed line-clamp-2 italic font-medium">
                                        "{assignment.submission_text.split('--- LUC INTEGRITY DEFENSE ---')[1]?.trim().slice(0, 180) || "Integrity verification passed."}..."
                                    </p>
                                </div>
                            )}
                            
                            <p className="text-[10px] text-slate-400 mt-2 leading-relaxed px-8">
                                Awarded for exceptional performance and verified architectural logic through the LUC Core Vetting system.
                            </p>
                        </div>
                    </div>

                    {/* Footer / Signatures */}
                    <div className="w-full flex justify-between items-end px-12 pb-4">
                        {/* Date */}
                        <div className="text-center w-48">
                            <div className="h-10 flex items-end justify-center pb-2 border-b-2 border-slate-300">
                                <span className="font-sans text-lg text-slate-700 font-medium">{completionDate}</span>
                            </div>
                            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold mt-2">Issue Date</p>
                        </div>

                        {/* QR / Verification */}
                        <div className="text-center w-32 flex flex-col items-center">
                            <div className="w-20 h-20 bg-slate-100 rounded-xl border-2 border-slate-200 flex items-center justify-center mb-1">
                                <Icon name="QrCode" size={48} className="text-slate-300" />
                            </div>
                            <p className="text-[8px] font-black text-slate-500 uppercase tracking-tighter">Scan to Verify</p>
                        </div>

                        {/* Signature */}
                        <div className="text-center w-48">
                            <div className="h-10 flex items-center justify-center border-b-2 border-slate-300 relative">
                                <span className="font-serif text-2xl text-slate-800 italic opacity-80">LUC Academy</span>
                            </div>
                            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold mt-2">LUC Administration</p>
                        </div>
                    </div>
                </div>

                {/* Bottom ID */}
                <div className="absolute bottom-2 w-full text-center pl-[25%] z-30">
                    <p className="text-[8px] text-slate-300 uppercase tracking-wider font-bold">
                        VERIFICATION KEY: {verificationId} • VIEW PROOF AT: LUCCADEMY.IO/VERIFY/{verificationId.toLowerCase()}
                    </p>
                </div>
            </div>

            <div className="flex gap-4">
                <Button variant="outline" iconName="Download" onClick={handlePrint}>
                    Download Certificate
                </Button>
                <Button variant="default" iconName="Share2" onClick={() => setShowShareModal(true)}>
                    Share Proof of Work
                </Button>
            </div>

            <AcademyShareModal
                isOpen={showShareModal}
                onClose={() => setShowShareModal(false)}
                type="certificate"
                data={course}
            />

            <style dangerouslySetInnerHTML={{
                __html: `
                @media print {
                    @page { 
                        size: landscape; 
                        margin: 0;
                    }
                    html, body {
                        width: 100%;
                        height: 100%;
                        margin: 0 !important;
                        padding: 0 !important;
                        overflow: hidden !important;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                    body * { visibility: hidden; }
                    .print-section, .print-section * { 
                        visibility: visible;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                    .print-section { 
                        position: fixed; 
                        left: 0; 
                        top: 0; 
                        width: 100%;
                        height: 100%;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        margin: 0;
                        padding: 0;
                        background: white;
                        overflow: hidden !important;
                        z-index: 9999;
                    }
                    .print-section > div {
                        width: ${isBadge ? 'auto' : '100%'} !important;
                        height: ${isBadge ? '100%' : 'auto'} !important;
                        aspect-ratio: ${isBadge ? '1.414/1' : '1.414/1'} !important;
                        max-width: ${isBadge ? '100vh' : '100%'} !important;
                        border-width: 0px !important; 
                        box-shadow: none !important;
                        background: white !important;
                    }
                    * {
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                    }
                }
            `}} />
        </div>
    );
};

export default Certificate;
