import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const CourseStudyMates = ({ courseId, userId, liveMates = [] }) => {
    const { addToast } = useToast();
    const [potentialMates, setPotentialMates] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (courseId && userId) {
            fetchPotentialMates();
        }
    }, [courseId, userId]);

    const fetchPotentialMates = async () => {
        setIsLoading(true);
        try {
            // 1. Get other students enrolled in this course (Strict Accuracy)
            const normalizedCourseId = String(courseId).trim();
            const { data: enrollments, error: enrollError } = await supabaseService.supabase
                .from('enrollments')
                .select(`
                    user_id,
                    profiles:user_id (id, full_name, avatar_url)
                `)
                .eq('item_id', normalizedCourseId)
                .neq('user_id', userId)
                .limit(10);

            if (enrollError) throw enrollError;

            // 2. Get existing mate relationships
            const { data: existingMates } = await supabaseService.supabase
                .from('study_mates')
                .select('requester_id, receiver_id')
                .or(`requester_id.eq.${userId},receiver_id.eq.${userId}`);

            const mateIds = (existingMates || []).map(m => 
                m.requester_id === userId ? m.receiver_id : m.requester_id
            );

            // 3. Categorize for Transparency
            let coursePeers = (enrollments || [])
                .map(e => e.profiles)
                .filter(p => p && !mateIds.includes(p.id))
                .map(p => ({ ...p, matchType: 'Course Peer' }));

            let recommendations = [...coursePeers];

            // 4. Fill with Global Scholars if needed (Explicitly Labeled)
            if (recommendations.length < 3) {
                const { data: globalEnrollments } = await supabaseService.supabase
                    .from('enrollments')
                    .select('user_id, profiles:user_id(id, full_name, avatar_url, last_seen_at, status_mode)')
                    .neq('user_id', userId)
                    .limit(30);

                if (globalEnrollments) {
                    const uniqueScholars = Array.from(new Map(
                        globalEnrollments.filter(e => e.profiles).map(e => [e.profiles.id, e.profiles])
                    ).values());

                    const validGlobal = uniqueScholars.filter(p => 
                        !mateIds.includes(p.id) && !recommendations.some(r => r.id === p.id)
                    );
                    
                    const needed = 3 - recommendations.length;
                    const fill = validGlobal.slice(0, needed).map(p => ({ ...p, matchType: 'Global Scholar' }));
                    recommendations = [...recommendations, ...fill];
                }
            }

            setPotentialMates(recommendations);
        } catch (error) {
            console.error('Error fetching course study mates:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const getStatus = (student) => {
        // 1. Priority 1: In the same Classroom (watching the same video)
        if (liveMates.some(m => String(m.id) === String(student.id))) {
            return { label: 'In Classroom', color: 'bg-emerald-500', pulse: true };
        }

        // 2. Priority 2: Status Mode override (DND, Away, etc)
        if (student.status_mode === 'offline') return { label: 'Offline', color: 'bg-slate-400', pulse: false };
        if (student.status_mode === 'dnd') return { label: 'DND', color: 'bg-red-500', pulse: false };
        if (student.status_mode === 'away') return { label: 'Away', color: 'bg-yellow-500', pulse: false };

        // 3. Priority 3: Platform Activity (Last seen within 5 minutes)
        if (student.last_seen_at) {
            const lastSeen = new Date(student.last_seen_at);
            const diffMinutes = (new Date() - lastSeen) / (1000 * 60);
            if (diffMinutes < 5) return { label: 'Online', color: 'bg-emerald-500', pulse: false };
        }

        return { label: 'Offline', color: 'bg-slate-400', pulse: false };
    };

    const sendRequest = async (targetId) => {
        try {
            const { error } = await supabaseService.supabase
                .from('study_mates')
                .insert([{ requester_id: userId, receiver_id: targetId, status: 'pending' }]);
            
            if (error) throw error;
            addToast('Study request sent!', 'success');
            // Optimistically remove from list
            setPotentialMates(prev => prev.filter(p => p.id !== targetId));
        } catch (error) {
            addToast('Could not send request', 'error');
        }
    };

    if (isLoading) return <div className="p-8 text-center opacity-40 animate-pulse text-xs font-bold uppercase">Scanning for Scholars...</div>;

    return (
        <div className="p-4 space-y-4">
            <div className="bg-primary/5 rounded-2xl p-4 border border-primary/10">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-primary mb-1">Study Collaboration</h4>
                <p className="text-[11px] font-medium text-muted-foreground leading-relaxed">
                    Partner with fellow scholars to finish this course 2x faster.
                </p>
            </div>

            <div className="space-y-3">
                {potentialMates.length === 0 ? (
                    <div className="py-10 text-center opacity-30">
                        <Icon name="Users" size={32} className="mx-auto mb-3" />
                        <p className="text-[10px] font-bold uppercase tracking-widest leading-relaxed px-4">
                            No other students found yet.
                        </p>
                    </div>
                ) : (
                    potentialMates.map(student => (
                        <div key={student.id} className="bg-card border border-border rounded-2xl p-3 flex items-center justify-between group hover:border-secondary/30 transition-all">
                            <div className="flex items-center gap-3">
                                <div className="relative">
                                    <img 
                                        src={student.avatar_url || `https://ui-avatars.com/api/?name=${student.full_name}&background=random`} 
                                        className="w-10 h-10 rounded-xl object-cover" 
                                    />
                                    {liveMates.some(m => String(m.id) === String(student.id)) && (
                                        <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-emerald-500 border-2 border-white dark:border-slate-900 rounded-full animate-pulse" />
                                    )}
                                </div>
                                <div>
                                    <p className="text-xs font-black truncate max-w-[120px]">{student.full_name}</p>
                                    <div className="flex flex-col">
                                        <p className={`text-[8px] font-black uppercase tracking-tighter ${
                                            student.matchType === 'Course Peer' ? 'text-secondary' : 'text-muted-foreground/60'
                                        }`}>
                                            {student.matchType}
                                        </p>
                                        
                                        {(() => {
                                            const status = getStatus(student);
                                            return (
                                                <div className={cn("flex items-center gap-1", status.label === 'Offline' && "opacity-40")}>
                                                    <div className={cn("w-1 h-1 rounded-full", status.color, status.pulse && "animate-pulse")} />
                                                    <span className={cn("text-[7px] font-black uppercase tracking-tighter", status.label !== 'Offline' && "text-primary")}>
                                                        {status.label}
                                                    </span>
                                                </div>
                                            );
                                        })()}
                                    </div>
                                </div>
                            </div>
                            <Button 
                                variant="ghost" 
                                size="sm" 
                                onClick={() => sendRequest(student.id)}
                                className="w-9 h-9 rounded-xl p-0 hover:bg-secondary/10 hover:text-secondary"
                            >
                                <Icon name="UserPlus" size={16} />
                            </Button>
                        </div>
                    ))
                )}
            </div>

            {potentialMates.length > 0 && (
                <p className="text-[9px] font-bold text-center text-muted-foreground uppercase mt-4">
                    Earn 20 LUC Credits for studying together
                </p>
            )}
        </div>
    );
};

export default CourseStudyMates;
