import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const CourseShowcase = ({ courseId }) => {
    const [showcase, setShowcase] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const fetchShowcase = async () => {
            setIsLoading(true);
            try {
                const data = await supabaseService.getCourseShowcase(courseId);
                setShowcase(data);
            } catch (error) {
                console.error("Failed to fetch showcase:", error);
            } finally {
                setIsLoading(false);
            }
        };

        if (courseId) fetchShowcase();
    }, [courseId]);

    if (isLoading) {
        return (
            <div className="py-20 flex flex-col items-center justify-center space-y-4">
                <div className="w-10 h-10 border-4 border-secondary border-t-transparent rounded-full animate-spin" />
                <p className="text-[10px] font-black text-muted-foreground uppercase tracking-widest animate-pulse">Entering Hall of Mastery...</p>
            </div>
        );
    }

    if (showcase.length === 0) {
        return (
            <div className="p-8 text-center space-y-6">
                <div className="w-20 h-20 bg-muted/30 rounded-[2rem] flex items-center justify-center mx-auto opacity-20">
                    <Icon name="Trophy" size={40} />
                </div>
                <div className="space-y-2">
                    <h4 className="text-sm font-black text-primary italic uppercase tracking-tight">The Hall is Empty</h4>
                    <p className="text-xs text-muted-foreground leading-relaxed">
                        Be the first to have your work vetted and showcased here. The LUC standard is waiting for its first Master.
                    </p>
                </div>
            </div>
        );
    }

    return (
        <div className="p-4 space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex items-center gap-3 px-2 mb-2">
                <div className="w-1.5 h-6 bg-secondary rounded-full shadow-[0_0_10px_rgba(8,145,178,0.5)]" />
                <div>
                    <h4 className="text-xs font-black text-primary italic uppercase tracking-widest">Alumni Submissions</h4>
                    <p className="text-[10px] text-muted-foreground font-medium uppercase tracking-tighter">Verified by LUC Core Integrity Vetting</p>
                </div>
            </div>

            <div className="space-y-4">
                {showcase.map((item, idx) => (
                    <div 
                        key={idx} 
                        className="group p-5 bg-card border border-border rounded-[2.5rem] hover:border-secondary/30 transition-all duration-500 shadow-sm hover:shadow-xl hover:shadow-secondary/5"
                    >
                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-2xl bg-muted overflow-hidden border border-border group-hover:scale-110 transition-transform">
                                {item.student_avatar ? (
                                    <img src={item.student_avatar} alt="" className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center bg-secondary/10 text-secondary">
                                        <Icon name="User" size={16} />
                                    </div>
                                )}
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-black text-primary italic truncate">{item.student_name}</p>
                                <div className="flex items-center gap-2">
                                    <span className="text-[10px] font-bold text-success flex items-center gap-1">
                                        <Icon name="ShieldCheck" size={10} />
                                        Vetted
                                    </span>
                                    <span className="text-[9px] text-muted-foreground font-medium">• {new Date(item.created_at).toLocaleDateString()}</span>
                                </div>
                            </div>
                            <div className="w-8 h-8 rounded-full bg-secondary/10 flex items-center justify-center text-secondary">
                                <Icon name="CheckCircle2" size={14} />
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div className="p-4 bg-muted/20 rounded-2xl border border-border/50 relative overflow-hidden group/text">
                                <div className="absolute top-0 right-0 p-2 opacity-10">
                                    <Icon name="Quote" size={24} />
                                </div>
                                <p className="text-xs text-muted-foreground leading-relaxed line-clamp-3 italic font-medium">
                                    {/* Extracting the defense part from the submission text if possible */}
                                    {item.submission_text.split('--- LUC INTEGRITY DEFENSE ---')[1]?.trim() || 
                                     item.submission_text.split('--- ASSIGNMENT ---')[1]?.trim() || 
                                     item.submission_text}
                                </p>
                            </div>

                            {item.file_url && (
                                <a 
                                    href={item.file_url} 
                                    target="_blank" 
                                    rel="noopener noreferrer"
                                    className="flex items-center justify-between p-3 bg-slate-950 rounded-2xl group/btn hover:bg-secondary transition-all duration-300"
                                >
                                    <div className="flex items-center gap-2">
                                        <Icon name="ExternalLink" size={12} className="text-white group-hover/btn:scale-125 transition-transform" />
                                        <span className="text-[10px] font-black text-white italic uppercase tracking-widest">View Project Work</span>
                                    </div>
                                    <Icon name="ChevronRight" size={12} className="text-white/30 group-hover/btn:translate-x-1 transition-transform" />
                                </a>
                            )}
                        </div>
                    </div>
                ))}
            </div>
            
            <div className="pt-4 text-center">
                <p className="text-[9px] font-black text-muted-foreground uppercase tracking-[0.2em]">
                    Build. Vette. Inspire.
                </p>
            </div>
        </div>
    );
};

export default CourseShowcase;
